using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int MaxRatePoints = 10;

    public int For(LoyaltyTier tier, int subtotalCents)
    {
        var ratePoints = Math.Min(BaseRatePoints(tier) + OrderSizeBonusPoints(subtotalCents), MaxRatePoints);
        var discountCents = subtotalCents * ratePoints / 100;

        return subtotalCents - discountCents;
    }

    private static int BaseRatePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
    };

    private static int OrderSizeBonusPoints(int subtotalCents) => subtotalCents switch
    {
        < 5000 => 0,
        < 20000 => 1,
        _ => 3,
    };
}
E
